package com.smartring.app.build

import com.smartring.app.data.db.AppDatabase
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

/**
 * The committed Room schema has to describe the database version the code declares.
 *
 * `app/schemas/` is generated by KSP on every build and is committed so that a schema
 * change is reviewable. The failure this guards against is bumping `@Database(version)`
 * — or editing an `@Entity` — without regenerating and committing the JSON. CI catches
 * that too, by diffing the generated schemas against the committed ones, but only after
 * a full Android build; this fails in seconds, next to the change that caused it.
 *
 * Only the *current* version's JSON can be asserted to exist: KSP emits the schema for
 * the version being built, so older versions' files exist only if they were committed
 * while they were current. v3 is the first, which is why there is no 1.json or 2.json —
 * MigrationTest writes those old schemas out by hand as raw SQL instead.
 */
class RoomSchemaTest {

    private val schemaDir: File by lazy {
        // Gradle runs unit tests with the module directory as the working directory;
        // some IDE runners use the project root. Accept either.
        listOf(File("schemas"), File("app/schemas"))
            .firstOrNull { it.isDirectory }
            ?: error("schemas/ not found from ${File(".").absolutePath}")
    }

    /**
     * Read out of the source rather than off the class.
     * `androidx.room.Database` is declared with BINARY retention, so it is not present
     * at runtime and `getAnnotation()` returns null — reflection here would fail for a
     * reason that has nothing to do with what this test is checking.
     */
    private val declaredVersion: Int by lazy {
        val src = listOf(
            File("src/main/java/com/smartring/app/data/db/AppDatabase.kt"),
            File("app/src/main/java/com/smartring/app/data/db/AppDatabase.kt"),
        ).firstOrNull { it.isFile }
            ?: error("AppDatabase.kt not found from ${File(".").absolutePath}")
        Regex("""version\s*=\s*(\d+)""").find(src.readText())?.groupValues?.get(1)?.toInt()
            ?: error("no `version = N` found in ${src.path}")
    }

    @Test
    fun `a schema is committed for the database version the code declares`() {
        val expected = File(schemaDir, "${AppDatabase::class.java.name}/$declaredVersion.json")
        assertTrue(
            "No committed Room schema for database version $declaredVersion. Build the app " +
                "and commit ${expected.path} — without it a schema change is invisible in review.",
            expected.isFile,
        )
    }

    @Test
    fun `the committed schema declares the same version as the code`() {
        val json = File(schemaDir, "${AppDatabase::class.java.name}/$declaredVersion.json").readText()
        // Deliberately a substring check rather than a JSON parse: the test module has no
        // JSON dependency, and the one field that matters here is unambiguous in the file.
        assertTrue(
            "The committed schema for version $declaredVersion does not declare that version",
            json.contains("\"version\": $declaredVersion"),
        )
        assertEquals(
            "Room's schema format version changed — the migration tooling assumes 1",
            true,
            json.contains("\"formatVersion\": 1"),
        )
    }
}
